/** Registra a composição atual da arena sem modificar código, física ou artes de produção. */
import fs from 'node:fs/promises';
const sleep=ms=>new Promise(r=>setTimeout(r,ms));
const cdp='http://127.0.0.1:9222',host='http://127.0.0.1:3000';
const tab=await(await fetch(cdp+'/json/new?'+encodeURIComponent(host),{method:'PUT'})).json();
const ws=new WebSocket(tab.webSocketDebuggerUrl);await new Promise(r=>ws.addEventListener('open',r,{once:true}));
let sequence=0;const pending=new Map();
ws.addEventListener('message',e=>{const m=JSON.parse(e.data);const p=pending.get(m.id);if(p){pending.delete(m.id);m.error?p.reject(Error(m.error.message)):p.resolve(m.result);}});
const send=(method,params={})=>new Promise((resolve,reject)=>{const id=++sequence;pending.set(id,{resolve,reject});ws.send(JSON.stringify({id,method,params}));});
const run=async expression=>{const r=await send('Runtime.evaluate',{expression,awaitPromise:true,returnByValue:true});if(r.exceptionDetails)throw Error(r.exceptionDetails.exception?.description||r.exceptionDetails.text);return r.result.value;};
const until=async(expression)=>{const end=Date.now()+30000;while(Date.now()<end){if(await run(expression))return;await sleep(80);}throw Error('Não ficou pronto: '+expression);};
const folder='docs/diario-ia/qa-resultados/arena-critica';await fs.mkdir(folder,{recursive:true});
async function capture(name,data=null){
 const bytes=data?Buffer.from(data.split(',')[1],'base64'):Buffer.from((await send('Page.captureScreenshot',{format:'png'})).data,'base64');
 await fs.writeFile(folder+'/'+name+'.png',bytes);await fs.writeFile('/tmp/legendgirl-arena-'+name+'.png',bytes);
}
try{
 await send('Page.enable');await send('Runtime.enable');await send('Emulation.setDeviceMetricsOverride',{width:1440,height:900,deviceScaleFactor:1,mobile:false});
 await send('Page.navigate',{url:host});await until('Boolean(window.game)');await run('game.assetsReady');
 await run(`(()=>{game.startDebugPhase('arena');game.setPaused(true);document.getElementById('start-overlay').style.display='none';})()`);
 await run(`Promise.all([game.state.toyRoomInstance.instance.arena.readyPromise,game.state.toyRoomInstance.instance.battle.readyPromise])`);
 await run(`(()=>{window.r=game.state.toyRoomInstance.instance;r.arena.state.status='COMBAT';r.battle.activate();r.battle.state.transition=null;r.introAlpha=0;r.introBannerTimer=0;})()`);
 for(const [name,width,height,mobile] of [['desktop',1440,900,false],['retrato',390,844,true],['paisagem',844,390,true]]){
  await send('Emulation.setDeviceMetricsOverride',{width,height,deviceScaleFactor:1,mobile});await sleep(200);
  await run(`r.mobilePresentation=${mobile};r.isTouchDevice=${mobile}`);
  const actors=name==='desktop'?[0,1,2,3]:[3];
  for(const index of actors){
   await run(`(()=>{const s=r.battle.state;s.index=${index};r.battle.spawn();s.enemy.state='IDLE';s.transition=null;s.jump=0;r.player.x=430;for(let i=0;i<240;i++)r.arena.camera.update(1,r.player,s.enemy,0);r.render();})()`);
   await capture(name+'-'+index);
  }
 }
 await send('Emulation.setDeviceMetricsOverride',{width:1440,height:900,deviceScaleFactor:1,mobile:false});await sleep(150);await run('r.mobilePresentation=false;r.isTouchDevice=false');
 const measurements=await run(`(async()=>{
  const {renderArenaEnvironment}=await import('./src/js/toy-room/ArenaEnvironment.js');
  const canvas=document.createElement('canvas');canvas.width=1600;canvas.height=1000;const ctx=canvas.getContext('2d');
  const draws=[];const bounds=new Map();
  const proxy=new Proxy(ctx,{get(target,key){if(key==='drawImage')return(image,...args)=>{
   const asset=[...r.assets.images].find(([key,value])=>value===image)?.[0]||'recorte-do-atlas';
   let b=bounds.get(image);if(!b){const c=document.createElement('canvas');c.width=image.width;c.height=image.height;const cctx=c.getContext('2d');cctx.drawImage(image,0,0);const p=cctx.getImageData(0,0,c.width,c.height).data;let x0=c.width,y0=c.height,x1=0,y1=0;for(let y=0;y<c.height;y++)for(let x=0;x<c.width;x++)if(p[(y*c.width+x)*4+3]>20){x0=Math.min(x0,x);x1=Math.max(x1,x);y0=Math.min(y0,y);y1=Math.max(y1,y);}b={x0,y0,x1,y1,width:c.width,height:c.height};bounds.set(image,b);}
   const [x,y,w,h]=args,m=target.getTransform();draws.push({order:draws.length,asset,rect:{x:x*m.a+m.e,y:y*m.d+m.f,w:w*m.a,h:h*m.d},visible:{left:(x+b.x0/b.width*w)*m.a+m.e,top:(y+b.y0/b.height*h)*m.d+m.f,right:(x+(b.x1+1)/b.width*w)*m.a+m.e,bottom:(y+(b.y1+1)/b.height*h)*m.d+m.f}});return target.drawImage(image,...args);
  };const v=Reflect.get(target,key,target);return typeof v==='function'?v.bind(target):v;},set(target,key,value){target[key]=value;return true;}});
  renderArenaEnvironment(proxy,r,r.arena.layout,0);window.arenaOverview=canvas.toDataURL('image/png');
  return {ground:r.arena.layout.ground,layout:r.arena.layout,draws};
 })()`);
 await capture('cenario-completo',await run('arenaOverview'));
 const foreground=await run(`(()=>{const s=r.battle.state;s.index=3;r.battle.spawn();r.battle.beginTransition(null);s.transition.elapsed=20;let calls=0;const original=r.battle.presentation.renderForeground;r.battle.presentation.renderForeground=(...args)=>{calls++;original(...args);};r.render();r.battle.presentation.renderForeground=original;return {calls,playerRendererInstalled:Boolean(r.battle.presentation.renderPlayer),transport:r.battle.transitionPlacement(true),temple:r.arena.layout.structures.find(x=>x.sourceId==='toy-chest')};})()`);
 await capture('entrada-urso');
 for(const [name,player,enemy] of [['extremo-esquerdo',210,620],['extremo-direito',970,1270]]){
  await run(`(()=>{r.battle.state.transition=null;r.player.x=${player};r.battle.state.enemy.x=${enemy};for(let i=0;i<240;i++)r.arena.camera.update(1,r.player,r.battle.state.enemy,0);r.render();})()`);await capture(name);
 }
 await run(`r.arena.state.status='TRANSFORMING';r.arena.state.elapsed=179;r.render()`);await capture('transformacao-179');
 const result={...measurements,foreground,scope:'Inspeção visual com estados/câmera preparados, sem simulação de campanha completa.'};
 await fs.writeFile(folder+'/medicoes.json',JSON.stringify(result,null,2));
 console.log(JSON.stringify({ground:result.ground,draws:result.draws.filter(x=>x.asset!=='toy-room-wallpaper-v1'),foregroundCalls:foreground.calls,playerRendererInstalled:foreground.playerRendererInstalled},null,2));
}finally{ws.close();await fetch(cdp+'/json/close/'+tab.id);}
